    SELECT id, 'tr', 'CODE_OUTPUT', 'BEGINNER', 'PUBLISHED', 'CLAUDE',
           $$Bu kod ne yazdırır?$$,
           $$int gun = 6;

switch (gun) {
    case 6:
        System.out.println("Cumartesi");
    case 7:
        System.out.println("Pazar");
    default:
        System.out.println("Hafta içi");
}$$, $$java$$,
           $$Eşleşen `case 6` çalışır ve `Cumartesi` yazdırılır. Hiçbir dalda `break` olmadığı için çalışma, eşleşip eşleşmediğine bakılmadan sonraki dallara düşer: önce `case 7`, sonra `default`. `switch` yalnızca bir `break`'e ya da kendi sonuna gelindiğinde biter; bu yüzden çıktı `Cumartesi` ile sınırlı kalmaz.$$,
           'claude-code@anthropic.com', now(), now(), now()
    FROM topic
    WHERE slug = 'switch'
    RETURNING id
)
INSERT INTO question_option (question_id, option_text, is_correct, sort_order)
SELECT new_question_tr2.id, v.option_text, v.is_correct, v.sort_order
FROM new_question_tr2
         CROSS JOIN (VALUES
        ($$Yalnızca `Cumartesi`$$, FALSE, 0),
        ($$`Cumartesi`, `Pazar` ve `Hafta içi`$$, TRUE, 1),
        ($$`Cumartesi` ve `Pazar`$$, FALSE, 2),
        ($$Yalnızca `Hafta içi`$$, FALSE, 3)
    ) AS v(option_text, is_correct, sort_order);

-- Pair 3 / EN (CODE_OUTPUT, BEGINNER)
WITH new_question_en3 AS (
    INSERT INTO question (topic_id, language, type, difficulty, status, source,
                           question, code_snippet, code_language, explanation,
                           reviewed_by, reviewed_at, created_at, updated_at)
    SELECT id, 'en', 'CODE_OUTPUT', 'BEGINNER', 'PUBLISHED', 'CLAUDE',
           $$What does this code print?$$,
           $$int month = 4;

switch (month) {
    case 3, 4, 5 -> System.out.println("Spring");
    case 6, 7, 8 -> System.out.println("Summer");
    default -> System.out.println("Other");
}$$, $$java$$,
           $$With the arrow syntax each branch runs on its own: there is no fall-through and no `break` is needed. `4` is one of the comma-separated values of the first branch, so only `Spring` is printed. Continuing into `Summer` and `Other` is what the classic syntax would do without `break`.$$,
           'claude-code@anthropic.com', now(), now(), now()
    FROM topic
    WHERE slug = 'switch'
    RETURNING id
)
INSERT INTO question_option (question_id, option_text, is_correct, sort_order)
SELECT new_question_en3.id, v.option_text, v.is_correct, v.sort_order
FROM new_question_en3
         CROSS JOIN (VALUES
        ($$`Spring`, then `Summer`$$, FALSE, 0),
        ($$`Spring`, `Summer`, then `Other`$$, FALSE, 1),
        ($$`Other`$$, FALSE, 2),
        ($$`Spring`$$, TRUE, 3)
    ) AS v(option_text, is_correct, sort_order);

-- Pair 3 / TR (CODE_OUTPUT, BEGINNER)
WITH new_question_tr3 AS (
    INSERT INTO question (topic_id, language, type, difficulty, status, source,
                           question, code_snippet, code_language, explanation,
                           reviewed_by, reviewed_at, created_at, updated_at)
    SELECT id, 'tr', 'CODE_OUTPUT', 'BEGINNER', 'PUBLISHED', 'CLAUDE',
           $$Bu kod ne yazdırır?$$,
           $$int puan = 1;

switch (puan) {
    case 1 -> System.out.println("Zayıf");
    case 2 -> System.out.println("Orta");
    case 3 -> System.out.println("İyi");
}

System.out.println("Bitti");$$, $$java$$,
           $$Ok sözdiziminde her dal bağımsız çalışır; fall-through yoktur ve `break` yazmak gerekmez. Bu yüzden yalnızca eşleşen dal `Zayıf` yazdırır, ardından `switch`'ten sonraki satır `Bitti` yazdırır. `Orta` ve `İyi`'nin de yazdırılması, `break` unutulmuş klasik sözdiziminin davranışı olurdu.$$,
           'claude-code@anthropic.com', now(), now(), now()
    FROM topic
    WHERE slug = 'switch'
    RETURNING id
)
INSERT INTO question_option (question_id, option_text, is_correct, sort_order)
SELECT new_question_tr3.id, v.option_text, v.is_correct, v.sort_order
FROM new_question_tr3
         CROSS JOIN (VALUES
        ($$`Zayıf`, `Orta`, `İyi`, sonra `Bitti`$$, FALSE, 0),
        ($$Yalnızca `Zayıf`$$, FALSE, 1),
        ($$`Zayıf`, sonra `Bitti`$$, TRUE, 2),
        ($$Kod derlenmez, çünkü dallarda `break` yok$$, FALSE, 3)
    ) AS v(option_text, is_correct, sort_order);

-- Pair 4 / EN (SINGLE_CHOICE, INTERMEDIATE)
WITH new_question_en4 AS (
    INSERT INTO question (topic_id, language, type, difficulty, status, source,
                           question, code_snippet, code_language, explanation,
                           reviewed_by, reviewed_at, created_at, updated_at)
    SELECT id, 'en', 'SINGLE_CHOICE', 'INTERMEDIATE', 'PUBLISHED', 'CLAUDE',
           $$In a switch expression, when is the `yield` keyword needed?$$,
           NULL, NULL,
           $$A branch written as a single expression after `->` produces its value directly. When a branch needs a block body with several steps, the compiler cannot tell which value the block stands for, so it must be named with `yield`. It is not a per-branch replacement for `break`, and it has nothing to do with how many values a `case` lists.$$,
           'claude-code@anthropic.com', now(), now(), now()
    FROM topic
    WHERE slug = 'switch'
    RETURNING id
)
INSERT INTO question_option (question_id, option_text, is_correct, sort_order)
SELECT new_question_en4.id, v.option_text, v.is_correct, v.sort_order
FROM new_question_en4
         CROSS JOIN (VALUES
        ($$In every branch, as the replacement for `break`$$, FALSE, 0),
        ($$Only in the `default` branch$$, FALSE, 1),
        ($$Whenever a `case` lists more than one value$$, FALSE, 2),
        ($$When a branch has a block body and must state the value it produces$$, TRUE, 3)
    ) AS v(option_text, is_correct, sort_order);

